import { render, sig, eff_on, mut, mem, html } from "/lib/solid/monke.js"


const M = mut({});
document.M = M;
const defer = (fn, t = 200) => setTimeout(fn, t)
const current_width = 400
let x = sig(0) 
let y = sig(0)
let w = sig(10)
let h = sig(0)
let videoWidth = current_width
let videoHeight = current_width

document.body.addEventListener("mousemove", (e) => {
  if (e.clientX) x.set(e.clientX-10)
  if (e.clientY) y.set(e.clientY-10)
})


document.onkeydown = (e) => {
  if (e.key == "L") w.set(w() + 10) 
  if (e.key == "H") w.set(w() - 10) 
  if (e.key == "J") h.set(h() + 10) 
  if (e.key == "K") h.set(h() - 10) 
  if (e.key == "Enter") { 
    crop(x(), y(), w(), h(), videoWidth, videoHeight) 
  }
}


let style = mem(() => `
  top: ${y()}px;
  left: ${x()}px;
  width: ${w()}px;
  height: ${h()}px;
  border: 1px red solid;
  position: fixed;
`)

const src = "/fs/media/beauty_c-cropped.mp4"

let loaded = function(e) {
  let vw = this.videoWidth
  let vh = this.videoHeight
  let div = vw/vh
  this.height = current_width/div
  videoHeight = this.height

  console.log("width", this.videoWidth)
  console.log("height", this.videoHeight)

  console.log("el width", this.width)
  console.log("el height", this.height)
}

function Root() {
  return html`
    style ---

    *{
      padding: 0px;
      margin: 0px;
    }

    ---
    div
      .cropper [style=${style}]
      video [ 
        src=${src}
        onloadedmetadata=${loaded}  
        controls=true
        width=${current_width+"px"}  
        ]
  `
}

function crop(x, y, w, h, videoWidth, videoHeight){
  let rename = src.replace(".mp4", "-cropped.mp4")

  fetch("/ffmpeg/", {
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify({
      action: "crop",
      input: src,
      output: rename,
      args: { x, y, h, w, videoWidth, videoHeight }
    })
  }).then((res) => console.log(res))
}


render(Root, document.body)
